    Console.WriteLine("=== SOURCE FILES FROM ARCHIVE ===");
    foreach (var entry in archive.Files) {
        if (entry.Key.Contains("Models.cs") || entry.Key.Contains("UserService.cs") || entry.Key.Contains("Program.cs")) {
            Console.WriteLine($"--- {entry.Key} ---");
