using System;
using System.IO;
using System.IO.Compression;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Extract embedded files from archive
var archive = build.SourceFilesArchive;
if (archive != null && archive.Length > 0) {
    Console.WriteLine("=== SOURCE FILES FROM ARCHIVE ===");
    using var ms = new MemoryStream(archive);
    using var zip = new ZipArchive(ms, ZipArchiveMode.Read);
    foreach (var entry in zip.Entries) {
        if (entry.FullName.Contains("Models.cs") || entry.FullName.Contains("UserService.cs") || entry.FullName.Contains("Program.cs")) {
            Console.WriteLine($"--- {entry.FullName} ---");
            using var reader = new StreamReader(entry.Open());
            Console.WriteLine(reader.ReadToEnd());
            Console.WriteLine();
        }
    }
} else {
    Console.WriteLine("No source archive found");
}

// Show errors with project info
Console.WriteLine("=== ERRORS ===");
build.VisitAllChildren<Error>(error => {
    Console.WriteLine($"[{error.Code}] {error.File}({error.LineNumber}): {error.Text}");
});

// Show projects
Console.WriteLine("\n=== PROJECTS ===");
build.VisitAllChildren<Project>(project => {
    Console.WriteLine($"  {project.Name}");
});
EOF

