using System;
using System.IO;
using System.IO.Compression;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// List all entries in archive
var archive = build.SourceFilesArchive;
if (archive != null && archive.Length > 0) {
    using var ms = new MemoryStream(archive);
    using var zip = new ZipArchive(ms, ZipArchiveMode.Read);
    Console.WriteLine($"Archive has {zip.Entries.Count} entries:");
    foreach (var entry in zip.Entries) {
        Console.WriteLine($"  {entry.FullName} ({entry.Length} bytes)");
    }
} else {
    Console.WriteLine("No source archive or empty");
}

// Check Api project - did it fail because of Services dependency?
Console.WriteLine("\n=== API PROJECT BUILD STATUS ===");
build.VisitAllChildren<Project>(project => {
    if (project.Name == "Api.csproj" || project.Name == "Services.csproj" || project.Name == "Core.csproj") {
        var hasErrors = false;
        project.VisitAllChildren<Error>(e => hasErrors = true);
        Console.WriteLine($"  {project.Name} - HasErrors: {hasErrors}");
    }
